'use strict';
(() => {
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='tm-privacy-v012-r7',categories=PrivacyEngine.definitions;
const actionLabels={redacted:'已脱敏 · 可转发',unchanged:'未命中 · 可转发',blocked:'已阻止外发'};
const reasons={unsupported_protocol:'当前协议不支持请求检查',request_too_large:'请求超过检查容量，未允许原文外发',duplicate_json_key:'JSON 包含重复字段，拒绝含糊的请求结构',invalid_json:'JSON 格式无效，无法安全改写',invalid_request:'缺少所选协议的必要请求结构',nesting_limit:'请求嵌套超过检查深度',uninspectable_content:'包含附件、非文本或无法安全改写的字段',detector_timeout:'识别处理超时',sensitive_field_name:'字段名中发现敏感内容，无法安全改写结构',sensitive_protocol_field:'模型或协议结构字段中发现敏感内容',residual_sensitive_value:'替换后校验仍发现已识别原值'};
const basePolicy={revision:1,categories:Object.keys(categories),max_kib:64,deadline_ms:1000,retention_days:30,fields:[]};
let state;try{state=JSON.parse(localStorage.getItem(KEY));}catch{}
if(state?.schema!==7)state={schema:7,policy:structuredClone(basePolicy),events:[{id:'risk-example-01',at:Date.now()-3600000,account:'Codex 主账号',protocol:'responses',action:'redacted',reason:null,policy_revision:1,source:'fixture',findings:[{category:'key',rule_id:'KEY_PREFIX',path:'/input',placeholder:'[API_KEY_1]'}],elapsed_ms:3,review:'unreviewed'},{id:'risk-example-02',at:Date.now()-7200000,account:'Claude 工作区',protocol:'messages',action:'blocked',reason:'uninspectable_content',policy_revision:1,source:'fixture',findings:[],elapsed_ms:1,review:'unreviewed'}],operations:[]};
let current='',draft=null,originalDraft='',lastResult=null,lastEventId=null,filters={action:'',category:'',q:''},page=1,toastTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('浏览器存储不可用，修改仅保留于本页');}}
function purge(){state.events=state.events.filter(e=>e.expires_at?e.expires_at>Date.now():Date.now()-e.at<state.policy.retention_days*86400000);}
purge();save();
function time(t){return new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2500);}
function opt(v,t,selected){return `<option value="${E(v)}" ${v===selected?'selected':''}>${E(t)}</option>`;}
function badge(action){return `<span class="badge ${action}">${actionLabels[action]}</span>`;}
function dirty(){return draft&&JSON.stringify(draft)!==originalDraft;}
function log(action,count=0){state.operations.unshift({action,count,at:Date.now()});state.operations=state.operations.slice(0,100);}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();}
function closeModal(){$('#modal').close();$('#modal-body').innerHTML='';}
$('#modal-close').onclick=closeModal;
const samples={
 credentials:'请帮我写一份服务器迁移检查清单。\n服务器地址：10.24.8.16\n账号：admin\n密码：DemoPass_987!\nAPI_KEY=sk-demo-1234567890abcdefghijkl\n请只说明步骤，不实际执行。',
 personal:'请帮我整理客户信息表。\n姓名：张三\n手机号：13800138000\n邮箱：sample@example.com\n身份证：110105199001011234\n家庭地址：北京市示例路8号\n把上述信息作为模板示例，不要联系客户。',
 repeat:'联系邮箱：sample@example.com\n确认收件人为 sample@example.com。\n密码：DemoPass_987!\n再次确认密码为 DemoPass_987!。',
 clean:'请将本周发布计划整理为三条待办：更新文档、检查兼容性、准备回滚。',
 ssh:'请检查下面的部署示例。\nssh root@10.24.8.16\nDATABASE_URL=postgresql://deploy:DemoPass_987@10.24.8.16:5432/app\n-----BEGIN PRIVATE KEY-----\nDEMO_PRIVATE_KEY_NOT_REAL\n-----END PRIVATE KEY-----',
 json:JSON.stringify({model:'custom-model-any-version',stream:true,messages:[{role:'user',content:'帮我检查配置，密码：DemoPass_987!，API_KEY=sk-demo-1234567890abcdefghijkl'}],metadata:{username:'deploy',password:'DemoPass_987!',host:'10.24.8.16'},temperature:0.7},null,2),
 attachment:JSON.stringify({model:'any-vision-model',messages:[{role:'user',content:[{type:'text',text:'请识别截图里的登录信息'},{type:'image_url',image_url:{url:'data:image/png;base64,DEMO'}}]}]},null,2)
};
function testPage(){
 $('#main').innerHTML=`<div class="heading"><div><h1>脱敏验证</h1><p>查看敏感信息在哪里被替换，以及模型将收到什么。</p></div><span class="badge clear">当前策略 v${state.policy.revision}</span></div><div class="step-strip"><span>① 输入请求</span><span>→</span><span>② 本机识别</span><span>→</span><b>③ 替换并校验</b><span>→</span><span>④ 允许转发 / 阻止外发</span></div><div class="notice">使用下方虚构样例验证流程。此页不发送网络请求；原文和替换映射不保存，切换页面即清除。未命中不代表不存在敏感信息。</div>${state.policy.categories.length<4?'<div class="notice warning">当前只检查已启用类别，未启用类别不会被替换。请先确认策略覆盖范围。</div>':''}<div class="field-row"><label class="field">接入账号<select id="test-account"><option>Codex 主账号</option><option>DeepSeek 生产</option><option>Claude 工作区</option></select></label><label class="field">请求协议<select id="test-protocol"><option value="responses">Responses</option><option value="chat">Chat Completions</option><option value="messages">Claude Messages</option></select></label><label class="field">输入方式<select id="test-format"><option value="text">文本内容</option><option value="json">完整 JSON 请求</option></select></label><label class="field">模型名称<input id="test-model" value="custom-model-any-version" autocomplete="off"></label></div><div class="example-buttons"><button data-example="credentials">账号密码与 API Key</button><button data-example="personal">个人信息</button><button data-example="ssh">服务器登录</button><button data-example="repeat">重复敏感值</button><button data-example="json">嵌套 JSON</button><button data-example="attachment">附件未覆盖</button><button data-example="clean">正常请求</button></div><div id="result-banner"></div><div class="compare"><section class="card"><div class="section-label"><h2>用户原始请求</h2><button id="clear-original" class="text-button">清空内容</button></div><label class="field"><textarea id="original" aria-label="用户原始请求" spellcheck="false" autocomplete="off" placeholder="输入虚构测试文本，或选择上方样例"></textarea></label><div class="test-action"><span class="muted">只检查请求，不改写模型响应</span><button id="run-test" class="primary">检查并脱敏</button></div></section><section class="card"><div class="section-label"><h2>模型实际将收到的请求</h2><span id="output-state" class="badge">等待检查</span></div><div id="output" class="output"><div class="empty-output">检查完成后显示最终请求<br>处理失败时不会生成可发送内容</div></div><div class="scope-info" id="result-meta"></div></section></div><section class="card"><div class="section-label"><h2>敏感片段处理明细</h2><a id="risk-link" hidden>查看风险记录 →</a></div><div id="findings"><div class="empty" style="padding:25px">检查后展示命中类型、字段位置与占位符，不展示原始秘密。</div></div></section>`;
 $('#original').value=samples.credentials;
 $$('[data-example]').forEach(b=>b.onclick=()=>{$('#original').value=samples[b.dataset.example];$('#test-format').value=['json','attachment'].includes(b.dataset.example)?'json':'text';if(['json','attachment'].includes(b.dataset.example))$('#test-protocol').value='chat';invalidate();});
 $('#test-account').onchange=()=>{const v=$('#test-account').value;$('#test-protocol').value=v.startsWith('Claude')?'messages':v.startsWith('DeepSeek')?'chat':'responses';invalidate();};
 for(const s of ['#original','#test-protocol','#test-format','#test-model'])$(s).addEventListener('input',invalidate);
 $('#clear-original').onclick=()=>{$('#original').value='';invalidate();};$('#run-test').onclick=runTest;
}
function invalidate(){lastResult=null;lastEventId=null;$('#result-banner').innerHTML='';$('#output').className='output';$('#output').innerHTML='<div class="empty-output">请求已修改，请重新检查</div>';$('#output-state').textContent='等待检查';$('#result-meta').innerHTML='';$('#risk-link').hidden=true;$('#findings').innerHTML='<p class="muted">尚未检查当前内容</p>';}
function safeFinding(f){return {category:f.category,rule_id:f.rule_id,path:safePath(f.path),placeholder:f.placeholder};}
function safePath(path){return path.split('/').map(p=>/^(?:input|messages|content|text|metadata|password|username|host|api_key|system|instructions|[0-9]+)$/.test(p)||p===''?p:'[字段]').join('/');}
function findingTable(findings){return `<div class="table-wrap"><table><thead><tr><th>敏感类型</th><th>位置</th><th>处理后占位符</th><th>命中规则</th></tr></thead><tbody>${findings.map(f=>`<tr><td>${E(categories[f.category].label)}</td><td><code>${E(f.path)}</code></td><td><code>${E(f.placeholder)}</code></td><td><code>${E(f.rule_id)}</code></td></tr>`).join('')}</tbody></table></div>`;}
function runTest(){
 if(!$('#original').value.trim()){toast('请先输入待检查内容');return;}
 let result;try{result=PrivacyEngine.protect($('#original').value,{protocol:$('#test-protocol').value,format:$('#test-format').value,model:$('#test-model').value,policy:structuredClone(state.policy)});}catch{result={action:'blocked',reason:'processing_error',output:null,findings:[],policy_revision:state.policy.revision,elapsed_ms:null};}
 lastResult=result;
 const findings=result.findings.map(safeFinding),id='risk-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);
 if(result.action!=='unchanged'){
  state.events.unshift({id,at:Date.now(),expires_at:Date.now()+state.policy.retention_days*86400000,account:$('#test-account').value,protocol:$('#test-protocol').value,action:result.action,reason:result.reason,policy_revision:result.policy_revision,source:'validation',findings,elapsed_ms:result.elapsed_ms,review:'unreviewed'});log('validation.risk_recorded',1);save();lastEventId=id;
 }else lastEventId=null;
 $('#result-banner').innerHTML=`<div class="result-banner ${result.action==='blocked'?'blocked':''}"><div><h2>${actionLabels[result.action]}</h2><p>${result.action==='blocked'?E(reasons[result.reason]||'处理失败，阻止原文外发'):result.action==='redacted'?`已替换 ${findings.length} 处敏感片段；正常业务文本保留。`:'所选规则未命中；不等于已证明内容无敏感信息。'}</p></div><span class="review-mark">本次为本机验证，未实际转发</span></div>`;
 $('#output').className='output'+(result.action==='blocked'?' blocked':'');$('#output').textContent=result.output||'没有可发送的请求。\n原始内容不会作为失败回退发给模型。';$('#output-state').textContent=result.action==='blocked'?'阻止外发':'检查通过';
 $('#result-meta').innerHTML=`<span class="badge">策略 v${result.policy_revision}</span><span class="badge">${result.elapsed_ms===null?'—':result.elapsed_ms+' ms'}</span><span class="badge">${result.action==='unchanged'?'不产生风险记录':'已登记风险元数据'}</span>`;
 $('#findings').innerHTML=findings.length?findingTable(findings):`<p class="muted">${result.action==='blocked'?'无法完成检查，无敏感值明细。':'未发现所选类别的敏感片段。'}</p>`;
 $('#risk-link').hidden=!lastEventId;$('#risk-link').href='#event/'+lastEventId;
}
function selectedEvents(){purge();return state.events.filter(e=>(!filters.action||e.action===filters.action)&&(!filters.category||e.findings.some(f=>f.category===filters.category))&&(!filters.q||e.id.includes(filters.q)));}
function eventsPage(){
 const rows=selectedEvents(),pages=Math.max(1,Math.ceil(rows.length/8));page=Math.min(page,pages);
 $('#main').innerHTML=`<div class="heading"><div><h1>风险记录</h1><p>查看哪些请求发生了敏感信息替换，哪些请求被阻止外发。</p></div><div class="actions"><button id="export-events">导出风险元数据</button><a class="primary button-link" href="#test" style="padding:10px 14px;border-radius:7px">验证脱敏效果</a></div></div><div class="metrics"><div class="metric"><small>当前筛选风险记录</small><strong>${rows.length}</strong><span class="hint">正常未命中请求不入风险表</span></div><div class="metric"><small>脱敏可转发</small><strong>${rows.filter(e=>e.action==='redacted').length}</strong><span class="hint">与上游调用成功分开判断</span></div><div class="metric alert"><small>阻止外发</small><strong>${rows.filter(e=>e.action==='blocked').length}</strong><span class="hint">无法安全处理的请求</span></div><div class="metric"><small>敏感片段</small><strong>${rows.reduce((n,e)=>n+e.findings.length,0)}</strong><span class="hint">只记录类型和占位符</span></div></div><div class="card table-card"><div class="toolbar"><input id="search-events" placeholder="搜索风险记录 ID" aria-label="搜索风险记录" value="${E(filters.q)}"><select id="filter-action" aria-label="处理结果">${opt('','全部处理结果',filters.action)}${opt('redacted','已脱敏 · 可转发',filters.action)}${opt('blocked','已阻止外发',filters.action)}</select><select id="filter-category" aria-label="敏感类型">${opt('','全部敏感类型',filters.category)}${Object.entries(categories).map(([k,v])=>opt(k,v.label,filters.category)).join('')}</select><button id="filter-reset">重置</button><button id="delete-events">清理当前筛选</button></div><div class="table-wrap"><table><thead><tr><th>时间 / 记录 ID</th><th>接入账号</th><th>处理结果</th><th>敏感类型</th><th>策略版本</th><th>来源</th><th></th></tr></thead><tbody>${rows.slice((page-1)*8,page*8).map(e=>`<tr><td>${time(e.at)}<small>${E(e.id)}</small></td><td>${E(e.account)}</td><td>${badge(e.action)}</td><td>${[...new Set(e.findings.map(f=>categories[f.category].label))].map(E).join('、')||'检查未完成'}</td><td>v${e.policy_revision}</td><td>${e.source==='fixture'?'历史样例':'脱敏验证'}</td><td><a data-detail="${e.id}" href="#event/${e.id}">查看 →</a></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">没有匹配的风险记录</div>'}</div><div class="paging"><span>${rows.length} 条 · 每页 8 条</span><div class="actions"><button id="prev" ${page===1?'disabled':''}>上一页</button><span>${page} / ${pages}</span><button id="next" ${page===pages?'disabled':''}>下一页</button></div></div></div><div class="notice">记录不保存原始请求、脱敏后全文或敏感值映射。这里的“可转发”是防护决策，不代表上游已收到或执行成功。</div>`;
 for(const [id,key]of [['filter-action','action'],['filter-category','category'],['search-events','q']])$('#'+id).onchange=e=>{filters[key]=e.target.value;page=1;eventsPage();};$('#filter-reset').onclick=()=>{filters={action:'',category:'',q:''};page=1;eventsPage();};$('#prev').onclick=()=>{page--;eventsPage();};$('#next').onclick=()=>{page++;eventsPage();};$('#delete-events').onclick=()=>deleteDialog(rows);$('#export-events').onclick=exportEvents;
}
function detailPage(id){const e=state.events.find(e=>e.id===id);if(!e){$('#main').innerHTML='<a href="#events" class="back">← 返回风险记录</a><div class="card empty">记录不存在或已清理</div>';return;}
 $('#main').innerHTML=`<a href="#events" class="back">← 返回风险记录</a><div class="heading"><div><h1>风险详情</h1><p class="record-id">${E(e.id)}</p></div>${badge(e.action)}</div><div class="notice ${e.action==='blocked'?'warning':''}">${e.action==='blocked'?E(reasons[e.reason]||'检查失败，原文未获准外发'):'敏感片段已替换，防护检查允许转发。原型没有真实上游调用。'}</div><div class="detail-summary"><section class="card"><h2>请求与处理</h2><dl class="facts"><dt>接入账号</dt><dd>${E(e.account)}</dd><dt>请求协议</dt><dd>${E(e.protocol)}</dd><dt>策略版本</dt><dd>v${e.policy_revision}</dd><dt>规则集</dt><dd>local-review-1</dd><dt>处理耗时</dt><dd>${e.elapsed_ms??'—'} ms</dd><dt>记录时间</dt><dd>${time(e.at)}</dd><dt>请求原文</dt><dd>不保存</dd><dt>原值映射</dt><dd>不保存</dd></dl></section><section class="card"><h2>规则效果反馈</h2><p class="muted">仅保存判断标签。不会自动放行该敏感值，也不把原文加入白名单。</p><div class="actions" style="margin-top:20px"><button id="feedback-correct" ${e.review==='correct'?'disabled':''}>识别正确</button><button id="feedback-false" ${e.review==='false_positive'?'disabled':''}>标记误识别</button></div><p id="feedback-state" style="margin-top:18px">当前：${({unreviewed:'未反馈',correct:'识别正确',false_positive:'误识别'})[e.review]}</p><p class="field-help">规则修改后，可使用虚构样例重新验证。历史记录无法恢复原始秘密。</p><a href="#test">进入脱敏验证 →</a></section></div><section class="card"><h2>敏感片段处理明细</h2>${e.findings.length?findingTable(e.findings):'<p class="muted">检查未完成，没有生成敏感值明细。</p>'}</section>`;
 for(const [sel,value]of [['feedback-correct','correct'],['feedback-false','false_positive']])$('#'+sel).onclick=()=>{e.review=value;log('risk.feedback',1);save();detailPage(id);toast('已保存反馈，不改变原防护决策');};
}
function policyPage(){draft=structuredClone(state.policy);originalDraft=JSON.stringify(draft);
 $('#main').innerHTML=`<div class="heading"><div><h1>脱敏策略</h1><p>定义请求发给模型之前，需要识别和替换哪些信息。</p></div><span class="badge clear">当前版本 v${state.policy.revision}</span></div><form id="policy-form" class="config-layout"><section class="card"><h2>保护方式</h2><div class="protect-summary"><b>识别敏感片段 → 自动替换 → 校验后转发</b><p class="muted">所有已接入账号统一生效；不按模型名称设置白名单。Provider 的上游鉴权密钥不属于待脱敏正文。</p></div><div class="scope-info"><span class="badge clear">本机处理 · 不把原文交给外部检测模型</span><span class="badge failed">处理失败 · 阻止外发</span></div></section><section class="card"><h2>敏感信息范围</h2><div class="policy-categories">${Object.entries(categories).map(([id,c])=>`<div class="policy-category"><label><input type="checkbox" data-category="${id}" ${draft.categories.includes(id)?'checked':''}>${c.label}</label><p>${({personal:'手机号、邮箱、身份证格式，以及带姓名、地址标签的内容。',account:'带账号、用户名、密码、口令等字段名或上下文标签的值。',server:'服务器地址、SSH 登录、数据库连接串及私钥片段。',key:'常见密钥格式、Bearer 令牌及 api_key、token 等字段。'})[id]}</p></div>`).join('')}</div><p class="field-help">任意未标注的密码、人名与业务字段无法保证识别。关闭类别后，该类别内容可能原样转发；至少保留一种类别。</p></section><section class="card"><h2>业务敏感字段</h2><p class="muted">为组织自己的配置字段增加识别规则。这里只填写字段名，不填写秘密值。</p><div class="rule-add"><label class="field">字段名<input id="custom-key" placeholder="例如 deploy_credential" maxlength="40" autocomplete="off"></label><label class="field">归属类别<select id="custom-category">${Object.entries(categories).map(([k,v])=>opt(k,v.label,'account')).join('')}</select></label><button type="button" id="add-field">添加规则</button></div><div id="field-list"></div></section><section class="card"><h2>检查容量与留存</h2><div class="form-grid"><label class="field">请求体上限（KiB）<input id="max-kib" type="number" min="4" max="1024" required value="${draft.max_kib}"></label><label class="field">检查时限（毫秒）<input id="deadline-ms" type="number" min="50" max="5000" required value="${draft.deadline_ms}"></label><label class="field">风险元数据保留（天）<input id="retention-days" type="number" min="1" max="365" required value="${draft.retention_days}"></label></div><div class="notice warning" style="margin-top:20px">附件、图片、音频、WebSocket 载荷等未覆盖内容会阻止外发，不会在检查失败后降级为原文直传。</div><p class="muted">原始请求和脱敏后全文不落库。缩短留存期收紧已有记录期限；延长不恢复已过期记录。</p></section><div id="policy-error" class="error" role="alert"></div><div class="save-bar"><span id="dirty-state">配置已同步</span><div class="actions"><button type="button" id="discard">放弃修改</button><button type="submit" class="primary" id="save-policy" disabled>保存策略</button></div></div></form>`;
 function changed(){draft.categories=$$('[data-category]:checked').map(e=>e.dataset.category);draft.max_kib=+$('#max-kib').value;draft.deadline_ms=+$('#deadline-ms').value;draft.retention_days=+$('#retention-days').value;$('#dirty-state').textContent=dirty()?'有未保存修改':'配置已同步';$('#save-policy').disabled=!dirty();}
 function fields(){ $('#field-list').innerHTML=draft.fields.map((f,i)=>`<div class="runtime-row"><span><code>${E(f.key)}</code><small>${categories[f.category].label}</small></span><button type="button" data-remove-field="${i}">移除</button></div>`).join('')||'<p class="field-help">尚无业务自定义字段，内置规则仍生效。</p>';$$('[data-remove-field]').forEach(b=>b.onclick=()=>{draft.fields.splice(+b.dataset.removeField,1);fields();changed();});}
 fields();$('#policy-form').oninput=changed;$('#policy-form').onchange=changed;$('#discard').onclick=policyPage;
 $('#add-field').onclick=()=>{const key=$('#custom-key').value.trim().toLowerCase();if(!/^[a-z][a-z0-9_]{1,39}$/.test(key)){toast('字段名使用2–40位字母、数字或下划线，以字母开头');return;}if(draft.fields.some(f=>f.key===key)){toast('该字段规则已存在');return;}if(draft.fields.length>=32){toast('最多32条业务字段规则');return;}draft.fields.push({key,category:$('#custom-category').value});$('#custom-key').value='';fields();changed();};
 $('#policy-form').onsubmit=ev=>{ev.preventDefault();changed();if(!draft.categories.length){$('#policy-error').textContent='至少启用一种敏感信息类别。';return;}let latest;try{latest=JSON.parse(localStorage.getItem(KEY));}catch{}if(latest&&latest.policy.revision!==draft.revision){$('#policy-error').innerHTML='策略已被其他页面更新。<button type="button" id="reload-policy">载入最新版本</button>';$('#reload-policy').onclick=()=>{state=latest;policyPage();};return;}
 const apply=()=>{let now;try{now=JSON.parse(localStorage.getItem(KEY));}catch{}if(now&&now.policy.revision!==draft.revision){closeModal();$('#policy-error').textContent='确认期间策略已变化，请重新载入。';return;}if(now)state=now;draft.revision++;state.policy=structuredClone(draft);for(const e of state.events)e.expires_at=Math.min(e.expires_at||Infinity,e.at+draft.retention_days*86400000);purge();log('policy.saved');save();closeModal();policyPage();toast('策略已保存，仅新请求使用新版本');};
 const removed=state.policy.categories.filter(c=>!draft.categories.includes(c));if(removed.length){openModal('确认缩小保护范围',`<p class="confirm-note">将停止检查：${removed.map(c=>categories[c].label).map(E).join('、')}。这些类别的内容可能原样转发给模型。</p><div class="modal-actions"><button type="button" id="cancel-policy">返回修改</button><button type="button" id="confirm-policy" class="danger">确认保存</button></div>`);$('#cancel-policy').onclick=closeModal;$('#confirm-policy').onclick=apply;}else apply();};
}
function deleteDialog(rows){const ids=rows.map(e=>e.id),expires=Date.now()+60000,revision=state.policy.revision;openModal('清理风险记录',`<p>本次预览选中 <b>${ids.length}</b> 条风险记录。</p><p class="confirm-note">只清理已预览的记录；之后新增的记录不受影响。预览有效期60秒。</p><label class="field">输入“清理”确认<input id="delete-text" autocomplete="off"></label><p id="delete-error" class="error"></p><div class="modal-actions"><button id="delete-confirm" class="danger" disabled>确认清理</button></div>`);$('#delete-text').oninput=()=>$('#delete-confirm').disabled=$('#delete-text').value!=='清理'||!ids.length;$('#delete-confirm').onclick=()=>{const latest=JSON.parse(localStorage.getItem(KEY));if(latest)state=latest;if(Date.now()>expires||revision!==state.policy.revision){$('#delete-error').textContent='预览已失效，请重新预览。';return;}const before=state.events.length,del=new Set(ids);state.events=state.events.filter(e=>!del.has(e.id));log('risk.deleted',before-state.events.length);save();closeModal();eventsPage();toast('已清理所选记录');};}
function exportEvents(){const result={generated_at:new Date().toISOString(),scope:{...filters},records:selectedEvents(),contains_original:false};const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='tracemason-privacy-risks.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出风险元数据');}
function route(){const target=location.hash.slice(1)||'test';if(current==='policy'&&target!=='policy'&&dirty()&&!confirm('放弃未保存的策略修改？')){location.hash='policy';return;}if(current==='test'&&target!=='test'){lastResult=null;lastEventId=null;}if(target!=='policy')draft=null;current=target;$$('[data-nav]').forEach(a=>{const active=target.startsWith('event/')?a.dataset.nav==='events':a.dataset.nav===target;a.classList.toggle('active',active);a.setAttribute('aria-current',active?'page':'false');});$('#breadcrumb').textContent='请求隐私防护 / '+(target==='policy'?'脱敏策略':target==='events'?'风险记录':target.startsWith('event/')?'风险详情':'脱敏验证');if(target==='policy')policyPage();else if(target==='events')eventsPage();else if(target.startsWith('event/'))detailPage(target.slice(6));else testPage();scrollTo(0,0);}
addEventListener('hashchange',route);addEventListener('storage',ev=>{if(ev.key!==KEY||!ev.newValue)return;const next=JSON.parse(ev.newValue);if(current==='policy'&&dirty()){toast('策略在其他页面有更新，保存前将校验版本');return;}state=next;if(current==='test'){invalidate();toast('策略已更新，请重新检查');}else route();});addEventListener('beforeunload',ev=>{if(dirty()){ev.preventDefault();ev.returnValue='';}});
route();window.PrivacyReview={ready:true,state:()=>structuredClone(state),result:()=>lastResult?structuredClone(lastResult):null};
})();
